fn all_prefixes(s: Vec<char>) -> Vec<Vec<char>> {
    let n = s.len();
    let mut result: Vec<Vec<char>> = Vec::with_capacity(n);

    for i in 0..n {
        // i-th prefix is the first (i+1) characters
        result.push(s[0..=i].to_vec());
    }

    result
}